#include "http.h"

#include <ctype.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>

size_t http_head_length(const char *buf, size_t len)
{
    /* Accept both CRLF CRLF and bare LF LF terminators. */
    for (size_t i = 0; i + 1 < len; i++) {
        if (buf[i] != '\n')
            continue;
        if (buf[i + 1] == '\n')
            return i + 2;
        if (buf[i + 1] == '\r' && i + 2 < len && buf[i + 2] == '\n')
            return i + 3;
    }
    return 0;
}

bool http_slice_eq(http_slice s, const char *lit)
{
    size_t n = strlen(lit);
    return s.len == n && memcmp(s.ptr, lit, n) == 0;
}

static bool slice_ieq(http_slice s, const char *lit)
{
    size_t n = strlen(lit);
    return s.len == n && strncasecmp(s.ptr, lit, n) == 0;
}

static http_slice trim(const char *p, const char *end)
{
    while (p < end && (*p == ' ' || *p == '\t'))
        p++;
    while (end > p && (end[-1] == ' ' || end[-1] == '\t' || end[-1] == '\r'))
        end--;
    return (http_slice){p, (size_t)(end - p)};
}

static bool is_tchar(unsigned char c)
{
    return isalnum(c) || (c && strchr("!#$%&'*+-.^_`|~", c));
}

/* Parses a Content-Length value: one or more digits, no sign, no overflow. */
static bool parse_length(http_slice v, size_t *out)
{
    if (v.len == 0)
        return false;
    size_t n = 0;
    for (size_t i = 0; i < v.len; i++) {
        unsigned char c = (unsigned char)v.ptr[i];
        if (!isdigit(c))
            return false;
        if (n > (SIZE_MAX - 9) / 10)
            return false;
        n = n * 10 + (size_t)(c - '0');
    }
    *out = n;
    return true;
}

static int parse_request_line(const char *p, const char *eol, http_request *req)
{
    const char *sp1 = memchr(p, ' ', (size_t)(eol - p));
    if (!sp1)
        return 400;
    const char *sp2 = memchr(sp1 + 1, ' ', (size_t)(eol - sp1 - 1));
    if (!sp2)
        return 400;

    req->method = (http_slice){p, (size_t)(sp1 - p)};
    req->target = (http_slice){sp1 + 1, (size_t)(sp2 - sp1 - 1)};
    http_slice version = trim(sp2 + 1, eol);

    if (req->method.len == 0 || req->target.len == 0)
        return 400;
    for (size_t i = 0; i < req->method.len; i++)
        if (!is_tchar((unsigned char)req->method.ptr[i]))
            return 400;
    if (version.len != 8 || memcmp(version.ptr, "HTTP/", 5) != 0 ||
        !isdigit((unsigned char)version.ptr[5]) || version.ptr[6] != '.' ||
        !isdigit((unsigned char)version.ptr[7]))
        return 400;
    if (version.ptr[5] != '1')
        return 505;
    return 0;
}

int http_parse_head(const char *buf, size_t head_len, http_request *req)
{
    const char *p = buf;
    const char *end = buf + head_len;

    memset(req, 0, sizeof *req);

    /* Tolerate leading empty lines (RFC 9112 section 2.2). */
    while (p < end && (*p == '\r' || *p == '\n'))
        p++;

    const char *eol = memchr(p, '\n', (size_t)(end - p));
    if (!eol)
        return 400;
    int rc = parse_request_line(p, eol, req);
    if (rc)
        return rc;

    bool have_length = false;
    for (p = eol + 1; p < end; p = eol + 1) {
        eol = memchr(p, '\n', (size_t)(end - p));
        if (!eol)
            return 400;
        http_slice line = trim(p, eol);
        if (line.len == 0)
            break; /* end of head */
        if (*p == ' ' || *p == '\t')
            return 400; /* obsolete line folding */

        const char *colon = memchr(line.ptr, ':', line.len);
        if (!colon || colon == line.ptr)
            return 400;
        http_slice name = {line.ptr, (size_t)(colon - line.ptr)};
        for (size_t i = 0; i < name.len; i++)
            if (!is_tchar((unsigned char)name.ptr[i]))
                return 400;
        http_slice value = trim(colon + 1, line.ptr + line.len);

        if (slice_ieq(name, "Content-Length")) {
            size_t n;
            if (!parse_length(value, &n))
                return 400;
            if (have_length && n != req->content_length)
                return 400;
            req->content_length = n;
            have_length = true;
        } else if (slice_ieq(name, "Transfer-Encoding")) {
            if (!slice_ieq(value, "identity"))
                return 501;
        } else if (slice_ieq(name, "Expect")) {
            if (slice_ieq(value, "100-continue"))
                req->expect_continue = true;
        }
    }
    return 0;
}

const char *http_reason(int status)
{
    switch (status) {
    case 100: return "Continue";
    case 200: return "OK";
    case 201: return "Created";
    case 204: return "No Content";
    case 400: return "Bad Request";
    case 404: return "Not Found";
    case 405: return "Method Not Allowed";
    case 408: return "Request Timeout";
    case 413: return "Content Too Large";
    case 431: return "Request Header Fields Too Large";
    case 500: return "Internal Server Error";
    case 501: return "Not Implemented";
    case 503: return "Service Unavailable";
    case 505: return "HTTP Version Not Supported";
    default:  return "Unknown";
    }
}

char *http_build_response(int status, const char *content_type,
                          const void *body, size_t body_len, size_t *out_len)
{
    char head[256];
    int n;
    /* 204 must not carry a body or Content-Length. */
    if (status == 204)
        n = snprintf(head, sizeof head,
                     "HTTP/1.1 204 No Content\r\nConnection: close\r\n\r\n");
    else
        n = snprintf(head, sizeof head,
                     "HTTP/1.1 %d %s\r\n"
                     "%s%s%s"
                     "Content-Length: %zu\r\n"
                     "Connection: close\r\n\r\n",
                     status, http_reason(status),
                     content_type ? "Content-Type: " : "",
                     content_type ? content_type : "",
                     content_type ? "\r\n" : "",
                     body_len);
    if (n < 0 || (size_t)n >= sizeof head)
        return NULL;
    if (status == 204)
        body_len = 0;

    char *out = malloc((size_t)n + body_len);
    if (!out)
        return NULL;
    memcpy(out, head, (size_t)n);
    if (body_len)
        memcpy(out + n, body, body_len);
    *out_len = (size_t)n + body_len;
    return out;
}

/* Minimal HTTP/1.1 request-head parsing and response formatting. */
#ifndef KVHTTP_HTTP_H
#define KVHTTP_HTTP_H

#include <stdbool.h>
#include <stddef.h>

typedef struct {
    const char *ptr;
    size_t len;
} http_slice;

typedef struct {
    http_slice method;
    http_slice target;
    size_t content_length;
    bool expect_continue;
} http_request;

/* Returns the length of the request head (through the blank line) if buf
 * contains a complete head, otherwise 0. */
size_t http_head_length(const char *buf, size_t len);

/* Parses a complete request head of length head_len. Returns 0 on success or
 * an HTTP status code (400, 501, 505) describing why the request is invalid.
 * Slices in *req point into buf. */
int http_parse_head(const char *buf, size_t head_len, http_request *req);

bool http_slice_eq(http_slice s, const char *lit);

const char *http_reason(int status);

/* Builds a complete response (head + body) in a freshly malloc'd buffer.
 * content_type may be NULL. Returns NULL on allocation failure. */
char *http_build_response(int status, const char *content_type,
                          const void *body, size_t body_len, size_t *out_len);

#endif

/* kvhttp: an in-memory HTTP/1.1 key-value server. Usage: app <port> */
#include <errno.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>

#include "server.h"
#include "store.h"

static int parse_port(const char *s, uint16_t *out)
{
    char *end;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno || end == s || *end != '\0' || v < 1 || v > 65535)
        return -1;
    *out = (uint16_t)v;
    return 0;
}

int main(int argc, char **argv)
{
    uint16_t port;
    if (argc != 2 || parse_port(argv[1], &port) != 0) {
        fprintf(stderr, "usage: %s <port>\n", argc ? argv[0] : "app");
        return 2;
    }

    signal(SIGPIPE, SIG_IGN);

    kv_store *store = kv_create();
    if (!store) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    int rc = server_run(port, store);
    kv_destroy(store);
    return rc;
}

#include "routes.h"

#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

static int respond(int status, const char *type, const void *body, size_t len,
                   char **out, size_t *out_len)
{
    *out = http_build_response(status, type, body, len, out_len);
    return *out ? 0 : -1;
}

int route_error(int status, char **out, size_t *out_len)
{
    return respond(status, NULL, NULL, 0, out, out_len);
}

static bool valid_key(http_slice k)
{
    if (k.len < 1 || k.len > KV_MAX_KEY_LEN)
        return false;
    for (size_t i = 0; i < k.len; i++) {
        char c = k.ptr[i];
        bool ok = (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
                  (c >= '0' && c <= '9') || c == '_' || c == '-';
        if (!ok)
            return false;
    }
    return true;
}

static int cmp_keys(const void *a, const void *b)
{
    return strcmp(*(const char *const *)a, *(const char *const *)b);
}

/* Keys are restricted to [A-Za-z0-9_-], so no JSON escaping is required. */
static int list_keys(const kv_store *store, char **out, size_t *out_len)
{
    size_t n = kv_count(store);
    const char **keys = malloc((n ? n : 1) * sizeof *keys);
    if (!keys)
        return route_error(500, out, out_len);
    kv_keys(store, keys);
    qsort(keys, n, sizeof *keys, cmp_keys);

    size_t cap = 2;
    for (size_t i = 0; i < n; i++)
        cap += strlen(keys[i]) + 3; /* quotes and comma */
    char *json = malloc(cap);
    if (!json) {
        free(keys);
        return route_error(500, out, out_len);
    }

    size_t len = 0;
    json[len++] = '[';
    for (size_t i = 0; i < n; i++) {
        if (i)
            json[len++] = ',';
        json[len++] = '"';
        size_t kl = strlen(keys[i]);
        memcpy(json + len, keys[i], kl);
        len += kl;
        json[len++] = '"';
    }
    json[len++] = ']';
    free(keys);

    int rc = respond(200, "application/json", json, len, out, out_len);
    free(json);
    return rc;
}

static int handle_key(kv_store *store, const http_request *req, http_slice key,
                      const char *body, char **out, size_t *out_len)
{
    if (http_slice_eq(req->method, "GET")) {
        const void *val;
        size_t vlen;
        if (!kv_get(store, key.ptr, key.len, &val, &vlen))
            return route_error(404, out, out_len);
        return respond(200, "application/octet-stream", val, vlen, out, out_len);
    }
    if (http_slice_eq(req->method, "PUT")) {
        bool created;
        if (kv_put(store, key.ptr, key.len, body, req->content_length, &created) != 0)
            return route_error(500, out, out_len);
        return route_error(created ? 201 : 200, out, out_len);
    }
    if (http_slice_eq(req->method, "DELETE"))
        return route_error(kv_delete(store, key.ptr, key.len) ? 204 : 404,
                           out, out_len);
    return route_error(405, out, out_len);
}

int route_request(kv_store *store, const http_request *req,
                  const char *body, char **out, size_t *out_len)
{
    http_slice path = req->target;
    static const char kv_prefix[] = "/kv/";
    const size_t kv_prefix_len = sizeof kv_prefix - 1;

    if (http_slice_eq(path, "/health")) {
        if (!http_slice_eq(req->method, "GET"))
            return route_error(405, out, out_len);
        return respond(200, "text/plain", "ok", 2, out, out_len);
    }
    if (http_slice_eq(path, "/kv")) {
        if (!http_slice_eq(req->method, "GET"))
            return route_error(405, out, out_len);
        return list_keys(store, out, out_len);
    }
    if (path.len >= kv_prefix_len && memcmp(path.ptr, kv_prefix, kv_prefix_len) == 0) {
        http_slice key = {path.ptr + kv_prefix_len, path.len - kv_prefix_len};
        if (!valid_key(key))
            return route_error(400, out, out_len);
        return handle_key(store, req, key, body, out, out_len);
    }
    return route_error(404, out, out_len);
}

/* Maps parsed HTTP requests onto key-value store operations. */
#ifndef KVHTTP_ROUTES_H
#define KVHTTP_ROUTES_H

#include <stddef.h>

#include "http.h"
#include "store.h"

enum { KV_MAX_KEY_LEN = 64, KV_MAX_VALUE_LEN = 1024 * 1024 };

/* Handles one request and returns a malloc'd serialized response in *out.
 * Returns 0 on success, -1 if no response could be allocated. */
int route_request(kv_store *store, const http_request *req,
                  const char *body, char **out, size_t *out_len);

/* Serializes a bodyless error response for the given status. */
int route_error(int status, char **out, size_t *out_len);

#endif

#include "server.h"

#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <netinet/tcp.h>
#include <poll.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <time.h>
#include <unistd.h>

#include "http.h"
#include "routes.h"

enum {
    MAX_CONNS = 4096,
    MAX_HEAD = 64 * 1024,
    INITIAL_BUF = 8 * 1024,
    IO_TIMEOUT_SEC = 30,   /* overall budget for receiving + sending */
    DRAIN_TIMEOUT_SEC = 2, /* lingering close after the response */
    POLL_TICK_MS = 1000,
};

typedef enum {
    ST_READ_HEAD,
    ST_READ_BODY,
    ST_WRITE,
    ST_DRAIN,
} conn_state;

typedef struct {
    int fd;
    conn_state state;
    time_t deadline;

    char *in;
    size_t in_len, in_cap;
    size_t head_len;
    http_request req;

    char *out;
    size_t out_len, out_off;
    bool continue_pending; /* need to send "100 Continue" before reading */
} conn;

static const char CONTINUE_LINE[] = "HTTP/1.1 100 Continue\r\n\r\n";

static time_t now_sec(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec;
}

static int set_nonblocking(int fd)
{
    int flags = fcntl(fd, F_GETFL);
    if (flags < 0 || fcntl(fd, F_SETFL, flags | O_NONBLOCK) < 0)
        return -1;
    return 0;
}

static int listen_on(uint16_t port)
{
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket");
        return -1;
    }
    int one = 1;
    setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);

    struct sockaddr_in addr = {
        .sin_family = AF_INET,
        .sin_port = htons(port),
        .sin_addr.s_addr = htonl(INADDR_LOOPBACK),
    };
    if (bind(fd, (struct sockaddr *)&addr, sizeof addr) < 0) {
        perror("bind");
        close(fd);
        return -1;
    }
    if (listen(fd, SOMAXCONN) < 0 || set_nonblocking(fd) < 0) {
        perror("listen");
        close(fd);
        return -1;
    }
    return fd;
}

static void conn_free(conn *c)
{
    close(c->fd);
    free(c->in);
    free(c->out);
    free(c);
}

static conn *conn_new(int fd)
{
    conn *c = calloc(1, sizeof *c);
    if (!c)
        return NULL;
    c->in = malloc(INITIAL_BUF);
    if (!c->in) {
        free(c);
        return NULL;
    }
    c->fd = fd;
    c->in_cap = INITIAL_BUF;
    c->state = ST_READ_HEAD;
    c->deadline = now_sec() + IO_TIMEOUT_SEC;
    return c;
}

/* Installs a response and switches the connection to writing. */
static void conn_respond(conn *c, char *resp, size_t len)
{
    free(c->out);
    c->out = resp;
    c->out_len = len;
    c->out_off = 0;
    c->continue_pending = false;
    c->state = ST_WRITE;
}

/* Returns false if even an error response cannot be produced. */
static bool conn_fail(conn *c, int status)
{
    char *resp;
    size_t len;
    if (route_error(status, &resp, &len) != 0)
        return false;
    conn_respond(c, resp, len);
    return true;
}

static bool reserve(conn *c, size_t need)
{
    if (need <= c->in_cap)
        return true;
    size_t cap = c->in_cap;
    while (cap < need)
        cap *= 2;
    /* The parsed request points into c->in; carry its slices across the move. */
    bool parsed = c->head_len != 0;
    size_t method_off = parsed ? (size_t)(c->req.method.ptr - c->in) : 0;
    size_t target_off = parsed ? (size_t)(c->req.target.ptr - c->in) : 0;
    char *p = realloc(c->in, cap);
    if (!p)
        return false;
    c->in = p;
    if (parsed) {
        c->req.method.ptr = p + method_off;
        c->req.target.ptr = p + target_off;
    }
    c->in_cap = cap;
    return true;
}

static bool dispatch(conn *c, kv_store *store)
{
    char *resp;
    size_t len;
    if (route_request(store, &c->req, c->in + c->head_len, &resp, &len) != 0)
        return false;
    conn_respond(c, resp, len);
    return true;
}

/* Advances the parser after new input. Returns false to drop the connection. */
static bool process_input(conn *c, kv_store *store)
{
    if (c->state == ST_READ_HEAD) {
        c->head_len = http_head_length(c->in, c->in_len);
        if (c->head_len == 0) {
            if (c->in_len >= MAX_HEAD)
                return conn_fail(c, 431);
            return true;
        }
        int rc = http_parse_head(c->in, c->head_len, &c->req);
        if (rc)
            return conn_fail(c, rc);
        if (c->req.content_length > KV_MAX_VALUE_LEN)
            return conn_fail(c, 413);
        if (!reserve(c, c->head_len + c->req.content_length))
            return conn_fail(c, 500);
        c->state = ST_READ_BODY;
        if (c->req.expect_continue && c->in_len < c->head_len + c->req.content_length)
            c->continue_pending = true;
    }
    if (c->state == ST_READ_BODY &&
        c->in_len >= c->head_len + c->req.content_length)
        return dispatch(c, store);
    return true;
}

/* Returns false when the connection should be closed. */
static bool on_readable(conn *c, kv_store *store)
{
    for (;;) {
        if (c->state == ST_DRAIN) {
            char scratch[16 * 1024];
            ssize_t n = recv(c->fd, scratch, sizeof scratch, 0);
            if (n > 0)
                continue;
            if (n < 0 && (errno == EAGAIN || errno == EWOULDBLOCK))
                return true;
            if (n < 0 && errno == EINTR)
                continue;
            return false; /* EOF or error: peer is done */
        }
        if (c->state != ST_READ_HEAD && c->state != ST_READ_BODY)
            return true;

        if (c->in_len == c->in_cap) {
            /* Only the head phase can fill the buffer; the body was reserved. */
            if (c->state != ST_READ_HEAD || !reserve(c, c->in_cap * 2))
                return conn_fail(c, 500);
        }
        size_t room = c->in_cap - c->in_len;
        if (c->state == ST_READ_HEAD && c->in_len + room > MAX_HEAD)
            room = c->in_len < MAX_HEAD ? MAX_HEAD - c->in_len : 0;
        if (c->state == ST_READ_BODY) {
            size_t want = c->head_len + c->req.content_length;
            room = want > c->in_len ? want - c->in_len : 0;
        }
        if (room == 0)
            return process_input(c, store);

        ssize_t n = recv(c->fd, c->in + c->in_len, room, 0);
        if (n > 0) {
            c->in_len += (size_t)n;
            if (!process_input(c, store))
                return false;
            continue;
        }
        if (n == 0)
            return false; /* client went away before finishing its request */
        if (errno == EAGAIN || errno == EWOULDBLOCK)
            return true;
        if (errno == EINTR)
            continue;
        return false;
    }
}

static bool on_writable(conn *c)
{
    if (c->continue_pending) {
        /* Best effort: the interim line is tiny and fits in the send buffer. */
        ssize_t n = send(c->fd, CONTINUE_LINE, sizeof CONTINUE_LINE - 1, 0);
        if (n < 0 && errno != EAGAIN && errno != EWOULDBLOCK && errno != EINTR)
            return false;
        if (n >= 0)
            c->continue_pending = false;
        return true;
    }
    while (c->state == ST_WRITE && c->out_off < c->out_len) {
        ssize_t n = send(c->fd, c->out + c->out_off, c->out_len - c->out_off, 0);
        if (n > 0) {
            c->out_off += (size_t)n;
            continue;
        }
        if (n < 0 && errno == EINTR)
            continue;
        if (n < 0 && (errno == EAGAIN || errno == EWOULDBLOCK))
            return true;
        return false;
    }
    if (c->state == ST_WRITE) {
        /* Response fully sent: half-close and drain so that unread request
         * bytes do not trigger a RST that could discard the response. */
        free(c->out);
        c->out = NULL;
        free(c->in);
        c->in = NULL;
        c->in_len = c->in_cap = 0;
        shutdown(c->fd, SHUT_WR);
        c->state = ST_DRAIN;
        c->deadline = now_sec() + DRAIN_TIMEOUT_SEC;
    }
    return true;
}

static short wanted_events(const conn *c)
{
    switch (c->state) {
    case ST_READ_HEAD:
    case ST_READ_BODY:
        return c->continue_pending ? (POLLIN | POLLOUT) : POLLIN;
    case ST_WRITE:
        return POLLOUT;
    case ST_DRAIN:
        return POLLIN;
    }
    return 0;
}

static void accept_all(int lfd, conn **conns, size_t *nconns)
{
    while (*nconns < MAX_CONNS) {
        int fd = accept(lfd, NULL, NULL);
        if (fd < 0) {
            if (errno == EINTR || errno == ECONNABORTED)
                continue;
            if (errno != EAGAIN && errno != EWOULDBLOCK)
                perror("accept");
            return;
        }
        int one = 1;
        setsockopt(fd, IPPROTO_TCP, TCP_NODELAY, &one, sizeof one);
#ifdef SO_NOSIGPIPE
        setsockopt(fd, SOL_SOCKET, SO_NOSIGPIPE, &one, sizeof one);
#endif
        conn *c = set_nonblocking(fd) == 0 ? conn_new(fd) : NULL;
        if (!c) {
            close(fd);
            continue;
        }
        conns[(*nconns)++] = c;
    }
}

int server_run(uint16_t port, kv_store *store)
{
    int lfd = listen_on(port);
    if (lfd < 0)
        return 1;

    conn **conns = calloc(MAX_CONNS, sizeof *conns);
    struct pollfd *pfds = calloc(MAX_CONNS + 1, sizeof *pfds);
    if (!conns || !pfds) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    size_t nconns = 0;

    for (;;) {
        pfds[0] = (struct pollfd){.fd = lfd, .events = nconns < MAX_CONNS ? POLLIN : 0};
        for (size_t i = 0; i < nconns; i++)
            pfds[i + 1] = (struct pollfd){.fd = conns[i]->fd, .events = wanted_events(conns[i])};

        int ready = poll(pfds, (nfds_t)nconns + 1, POLL_TICK_MS);
        if (ready < 0) {
            if (errno == EINTR)
                continue;
            perror("poll");
            return 1;
        }

        time_t now = now_sec();
        size_t polled = nconns;
        size_t kept = 0;
        for (size_t i = 0; i < polled; i++) {
            conn *c = conns[i];
            short re = pfds[i + 1].revents;
            bool alive = true;

            if (re & (POLLIN | POLLHUP | POLLERR))
                alive = on_readable(c, store);
            if (alive && (re & (POLLOUT | POLLERR)))
                alive = on_writable(c);
            /* A freshly produced response is usually writable right away. */
            if (alive && c->state == ST_WRITE && !(re & POLLOUT))
                alive = on_writable(c);
            if (alive && now >= c->deadline)
                alive = false;

            if (alive)
                conns[kept++] = c;
            else
                conn_free(c);
        }
        nconns = kept;

        if (pfds[0].revents & POLLIN)
            accept_all(lfd, conns, &nconns);
    }
}

